    private Icons() {
    }

    public static Node icon(String path) {
        return icon(path, 18);
    }

    /** Tạo biểu tượng kích thước {@code size}px; màu lấy từ CSS lớp {@code .icon} ( -fx-fill ). */
    public static Node icon(String path, double size) {
        SVGPath svg = new SVGPath();
        svg.setContent(path);
        svg.getStyleClass().add("icon");
        double scale = size / 24.0;
        svg.setScaleX(scale);
        svg.setScaleY(scale);
        StackPane wrap = new StackPane(svg);
        wrap.setMinSize(size, size);
        wrap.setPrefSize(size, size);
        wrap.setMaxSize(size, size);
        wrap.getStyleClass().add("icon-wrap");
        return wrap;
    }
